// Імпортуємо типи PostsManager та GalleryManager з відповідних модулів
// Ключове слово 'type' вказує, що імпортуються лише типи, а не значення
// Це дозволяє TypeScript оптимізувати збірку, виключаючи непотрібний код
import type { PostsManager } from '../modules/posts/PostsManager.js';
import type { GalleryManager } from '../modules/gallery/GalleryManager.js';

// Оголошуємо глобальне розширення інтерфейсу Window
// Це дозволяє додати власні властивості до глобального об'єкта window
declare global {
  // Розширюємо стандартний інтерфейс Window браузера
  interface Window {
    // Додаємо опціональну властивість postsManager для доступу до менеджера постів
    // Символ ? означає, що ця властивість може бути відсутньою (undefined)
    postsManager?: PostsManager;
    
    // Додаємо опціональну властивість galleryManager для доступу до менеджера галереї
    // Це дозволяє викликати методи цих менеджерів безпосередньо з глобального об'єкта window
    galleryManager?: GalleryManager;
  }
}

// Експортуємо порожній об'єкт
// Це необхідно для того, щоб TypeScript обробляв файл як модуль
// Без цього рядка файл вважався б глобальним скриптом, а не модулем
// У модулях ES6 кожен файл є окремим модулем, і ця конструкція підтверджує це
export {};